import sys
sys.path.insert(0, '/workspace/task/source')
from pycalphad import Database, Model, variables as v

dbf = Database('/workspace/task/fixtures/al_fe_c_benchmark.tdb')
comps = ['AL', 'FE', 'VA']

def energies(y, T=1250.0):
    out = {}
    for phase in ('BCC_4SL', 'BCC_NOB'):
        mod = Model(dbf, comps, phase)
        state = {v.T: T, v.P: 101325.0}
        for k in mod.variables:
            if isinstance(k, v.SiteFraction):
                state[k] = y.get(k.sublattice_index, {}).get(k.species.name, 1.0)
        out[phase] = float(mod.energy.xreplace(state))
        # individual contributions
        for name, val in mod.models.items():
            state_terms = float(val.xreplace(state))
            out[phase + ':' + name] = state_terms
    return out

configs = [
    ({0: {'AL':1.}, 1: {'AL':1.}, 2: {'FE':1.}, 3: {'FE':1.}}, 'B2 config A (AL,AL,FE,FE)'),
    ({0: {'AL':1.}, 1: {'FE':1.}, 2: {'AL':1.}, 3: {'FE':1.}}, 'B2 config B (AL,FE,AL,FE)'),
    ({0: {'AL':1.}, 1: {'AL':1.}, 2: {'AL':0.5,'FE':0.5}, 3: {'AL':0.5,'FE':0.5}}, 'D03-ish half order'),
    ({0: {'AL':0.5,'FE':0.5}, 1: {'AL':0.5,'FE':0.5}, 2: {'AL':0.5,'FE':0.5}, 3: {'AL':0.5,'FE':0.5}}, 'disordered'),
]
for y, tag in configs:
    r = energies(y)
    print(tag, f"4SL={r['BCC_4SL']:.2f} NOB={r['BCC_NOB']:.2f} diff={r['BCC_4SL']-r['BCC_NOB']:.6f}")
    print('   4SL:', {k.split(':')[1]: round(v,1) for k,v in r.items() if k.startswith('BCC_4SL:')})
    print('   NOB:', {k.split(':')[1]: round(v,1) for k,v in r.items() if k.startswith('BCC_NOB:')})
